// Copies shared/pricing.ts into the extensions that need it. `shopify app
// function build` bundles only what's inside the extension folder, so the
// function can't import ../../shared directly. Never edit the copy —
// test/shared-copy.test.ts fails if it drifts.
import { readFileSync, writeFileSync } from "node:fs";

export const HEADER =
  "// GENERATED by scripts/sync-shared.mjs from shared/pricing.ts — do not edit.\n";
export const TARGETS = [
  "extensions/protection-validation/src/pricing.ts",
  "extensions/protection-transform/src/pricing.ts",
  "extensions/protection-checkout/src/pricing.ts",
];

const src = readFileSync("shared/pricing.ts", "utf8");
for (const target of TARGETS) {
  writeFileSync(target, HEADER + src);
  console.log(`synced ${target}`);
}
